
.internal-link {
	display: flex;
	align-items: center;
	gap: 10px;

	&__icon {
		display: flex;
		width: 32px;
		height: 32px;
		border-radius: 16px;
		color: white;
		background-color: var(--color-text-maxcontrast);
		align-items: center;
		justify-content: center;
	}

	&__label {
		display: flex;
		flex-direction: column;
		flex: 1 auto;
		line-height: 1.2em;

		&__hint {
			color: var(--color-text-maxcontrast);
		}
	}
}
