
.edit-calendar-modal {
	padding: 20px;
	display: flex;
	flex-direction: column;

	&__header {
		margin-top: 0;
	}

	&__header,
	&__sharing-header {
		// Same font size the header of NcDialog (no variable available a this point)
		font-size: 21px;
	}

	&__header_subtitle {
		display: block;
		color: var(--color-text-maxcontrast);
		font-size: 1rem;
		font-weight: normal;
	}

	&__name-and-color {
		display: flex;
		align-items: center;
		gap: 10px;
		margin-bottom: 10px;

		&__color {
			&__dot {
				width: 24px;
				height: 24px;
				border-radius: 12px;
			}
		}

		&__name {
			flex: 1 auto;
		}
	}

	&__actions {
		display: flex;
		gap: 10px;
		margin-top: 10px;

		button:last-of-type {
			margin-inline-start: auto;
		}
	}

	&__sharing-header {
		margin-top: 10px;
	}

	&__sharing {
		display: flex;
		flex-direction: column;
		gap: 5px;
	}

	&__default-alarm {
		margin-bottom: calc(var(--default-grid-baseline) * 2);

		&__label {
			display: block;
			margin-bottom: var(--default-grid-baseline);
			font-weight: bold;
		}

		&__select {
			width: 100%;
		}

		&__hint {
			margin-top: var(--default-grid-baseline);
			color: var(--color-text-maxcontrast);
		}
	}

	.checkbox-content {
		margin-inline-start: 25px;
	}
}

.app-navigation-spacer {
	list-style-type: none;
}
