
.attendee-display {
	display: flex;
	align-items: center;
	gap: var(--default-grid-baseline);
	overflow: hidden;
	margin-bottom: calc(var(--default-grid-baseline) * 4);

	&--compact {
		margin-bottom: 0;
	}

	&__name {
		text-overflow: ellipsis;
		overflow: hidden;
		white-space: nowrap;
	}

	&__email {
		margin-inline-start: calc(var(--default-grid-baseline) * 2);
		opacity: 0.45;
	}

	&__button-wrapper {
		flex-shrink: 0;
		display: flex;
	}

	&__button {
		flex-shrink: 0;
	}
}
